const rawText = $input.first().json.text || $input.first().json.output || '{}';

let parsed = { ingredients: [], condition: 'AND', method: '' };
try {
  const cleaned = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  const obj = JSON.parse(cleaned);
  parsed = {
    ingredients: Array.isArray(obj.ingredients) ? obj.ingredients.filter(Boolean) : (obj.ingredient ? [obj.ingredient] : []),
    condition: obj.condition === 'OR' ? 'OR' : 'AND',
    method: obj.method || ''
  };
} catch (e) {
  parsed = { ingredients: [], condition: 'AND', method: '' };
}

// Webhook 노드에서 원본 데이터 안전하게 가져오기
const webhookData = $('Webhook').first().json;
const webhookBody = webhookData.body && typeof webhookData.body === 'object' ? webhookData.body : webhookData;

const originalQuery = webhookBody.query || webhookBody.question || webhookData.query || webhookData.question || '';
const profile = webhookBody.profile !== undefined ? webhookBody.profile : webhookData.profile;
const sessionId = webhookBody.sessionId || webhookData.sessionId || null;
const type = webhookBody.type || webhookData.type || 'recipe';

// 검색 쿼리 고도화 (추출된 재료들을 모두 조합)
let searchTargetQuery = originalQuery;
if (parsed.ingredients.length > 0) {
  searchTargetQuery = `${parsed.ingredients.join(' ')} ${parsed.method || ''} 레시피 요리`.trim();
}

return [{
  json: {
    query: originalQuery,
    searchQuery: searchTargetQuery,
    ingredients: parsed.ingredients,
    ingredient: parsed.ingredients[0] || '', // 하위 호환용 유지
    condition: parsed.condition,
    method: parsed.method,
    profile,
    sessionId,
    type
  }
}];

const items = $input.all();
const embedding = items[0].json.data[0].embedding;

return [{
  json: {
    vector: embedding,
    limit: 20,       
    // 다중 재료 교집합 확보를 위해 10 ->20으로 확장
    with_payload: true
  }
}];
